<html lang="zh-CN">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>我与地坛</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Noto+Serif+SC:wght@300;400;600;700&display=swap" rel="stylesheet" />
  <style>
    *, *::before, *::after {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    :root {
      --ink:        #2c1f14;
      --ink-light:  #5a4535;
      --paper:      #f5f0e8;
      --paper-dark: #ede6d6;
      --red:        #8b2020;
      --gold:       #b8860b;
      --divider:    rgba(139, 32, 32, 0.25);
    }

    html {
      font-size: 18px;
      scroll-behavior: smooth;
    }

    body {
      background-color: var(--paper);
      color: var(--ink);
      font-family: 'Noto Serif SC', 'Songti SC', 'SimSun', serif;
      min-height: 100vh;
      position: relative;
      overflow-x: hidden;
    }

    /* ── Subtle texture overlay ── */
    body::before {
      content: '';
      position: fixed;
      inset: 0;
      background-image:
        repeating-linear-gradient(
          0deg,
          transparent,
          transparent 34px,
          rgba(180, 150, 100, 0.07) 34px,
          rgba(180, 150, 100, 0.07) 35px
        );
      pointer-events: none;
      z-index: 0;
    }

    /* ── Decorative side borders ── */
    body::after {
      content: '';
      position: fixed;
      top: 0; left: 0;
      width: 6px;
      height: 100%;
      background: linear-gradient(to bottom, var(--red), #c0392b 40%, var(--gold), var(--red));
      z-index: 10;
    }

    .right-border {
      position: fixed;
      top: 0; right: 0;
      width: 6px;
      height: 100%;
      background: linear-gradient(to bottom, var(--red), #c0392b 40%, var(--gold), var(--red));
      z-index: 10;
    }

    /* ── Page wrapper ── */
    .page {
      position: relative;
      z-index: 1;
      max-width: 720px;
      margin: 0 auto;
      padding: 80px 40px 100px;
    }

    /* ── Header ── */
    header {
      text-align: center;
      margin-bottom: 60px;
    }

    .seal {
      display: inline-block;
      width: 64px;
      height: 64px;
      border: 3px solid var(--red);
      border-radius: 4px;
      line-height: 64px;
      font-size: 1.5rem;
      color: var(--red);
      letter-spacing: 2px;
      margin-bottom: 28px;
      position: relative;
      font-weight: 700;
      background: transparent;
    }

    .seal::before, .seal::after {
      content: '';
      position: absolute;
      background: var(--red);
    }
    .seal::before { top: 6px; left: 6px; right: 6px; height: 1px; }
    .seal::after  { bottom: 6px; left: 6px; right: 6px; height: 1px; }

    h1 {
      font-size: 3rem;
      font-weight: 700;
      letter-spacing: 0.25em;
      color: var(--ink);
      line-height: 1.2;
      margin-bottom: 16px;
    }

    .subtitle {
      font-size: 0.85rem;
      color: var(--ink-light);
      letter-spacing: 0.3em;
      margin-top: 10px;
    }

    /* ── Divider ── */
    .divider {
      display: flex;
      align-items: center;
      gap: 12px;
      margin: 48px 0;
      color: var(--divider);
    }
    .divider::before,
    .divider::after {
      content: '';
      flex: 1;
      height: 1px;
      background: var(--divider);
    }
